		LmdbNativeCostVector quote = tailQuote(source, star(P3, B, 150_000D), tail(BranchRole.COUNT, S, 0, 0), 1);
		// the 150000-row plane exceeds twice the work of the 1024 paid probes: the executor abandons the sweep at
